end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<char>;
  var resultList := new List<string>;
  var currentString := '';

  for var i := 1 to parenString.Length do
  begin
    var currentChar := parenString[i];
    if currentChar = ' ' then
      continue;

    if currentChar = '(' then
      stack.Push('(')
    else if currentChar = ')' then
    begin
      if stack.Count = 0 then
      begin
        resultList.Add(currentString);
        currentString := '';
      end
      else
      begin
        currentString += ')';
        stack.Pop();
      end;
    end;
  end;

  Result := resultList.ToArray();
end;


