function FindClosestElements(numbers: array of real): (real, real);
begin
  &Array.Sort(numbers);
  var closest := (real.MaxValue, real.MaxValue);
  for var i := 0 to numbers.Length - 2 do
  begin
    if (closest[0] > numbers[i]) and (closest[0] - numbers[i] < closest[1] - numbers[i + 1]) then
      closest := (numbers[i], numbers[i + 1]);
    if (closest[1] > numbers[i]) and (numbers[i + 1] - numbers[i] < closest[1] - closest[0]) then
      closest := (numbers[i + 1], numbers[i]);
  end;
  Result := closest;
end;


function RescaleToUnit(numbers: array of real): array of real;
