function EncodeCyclic(s : string): string;
{ returns encoded string by cycling groups of three characters. }
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;
  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][1];
  end;
  Result := string.Join('', groups.ToArray);
end;
function DecodeCyclic(s: string): string;
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;

  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][0];
  end;

  Result := string.Join('', groups.ToArray);
end;


function PrimeFib(n: integer): integer;

  function IsPrime(num: integer): boolean;
  begin
    if num < 2 then
      Result := False
    else
    begin
      for var i := 2 to Round(Sqrt(num)) do
        if num mod i = 0 then
        begin
          Result := False;
          exit;
        end;
      Result := True;
    end;
  end;

  function Fibonacci(n: integer): integer;
  begin
    if n = 0 then
      Result := 0
    else if n = 1 then
      Result := 1
    else
      Result := Fibonacci(n - 1) + Fibonacci(n - 2);
  end;

begin
  var count := 0;
  var i := 0;
  while count < n do
  begin
    var fib := Fibonacci(i);
    if fib > 1 then
    begin
      if IsPrime(fib) then
      begin
        count += 1;
        Result := fib;
      end;
    end;
    i += 1;
  end;
end;


function TriplesSumToZero(l: array of integer): boolean;
begin
  var sorted_l := l.ToList;
  sorted_l.Sort;
  for var i := 0 to sorted_l.Count - 3 do
  begin
    var left := i + 1;
    var right := sorted_l.Count - 1;
    while left < right do
    begin
      var sum := sorted_l[i] + sorted_l[left] + sorted_l[right];
      if sum = 0 then
      begin
        Result := True;
        exit;
      end
      else if sum < 0 then
        left += 1
      else
        right -= 1;
    end;
  end;
  Result := False;
end;


