function Fib4(n: integer): integer;
begin
  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 0
  else if n = 2 then
    Result := 2
  else if n = 3 then
    Result := 0
  else
  begin
    var fib4 := new integer[n + 1];
    fib4[0] := 0;
    fib4[1] := 0;
    fib4[2] := 2;
    fib4[3] := 0;
    for var i := 4 to n do
      fib4[i] := fib4[i-1] + fib4[i-2] + fib4[i-3] + fib4[i-4];
    Result := fib4[n];
  end;
end;


