end;


function Monotonic(l: array of integer): boolean;
begin
  if l.Length <= 1 then
  begin
    Result := True;
    exit;
  end;

  var direction := l[0];
  foreach var num in l do
  begin
    if direction = 0 then
    begin
      Result := True;
      exit;
    end;

    if direction * num < 0 then
    begin
      Result := False;
      exit;
    end;

    direction := num;
  end;

  Result := True;
end;


function Common(l1, l2: array of integer): array of integer;
begin
  var common := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < l1.Length) and (j < l2.Length) do
  begin
    if l1[i] = l2[j] then
    begin
      if (common.Count = 0) or (common[common.Count - 1] <> l1[i]) then
        common.Add(l1[i]);
      i += 1;
      j += 1;
    end
    else if l1[i] < l2[j] then
      i += 1
    else
      j += 1;
  end;

  Result := common.ToArray;
end;


function LargestPrimeFactor(n: integer): integer;
