function CorrectBracketing(brackets: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var bracket in brackets do
  begin
    if bracket = '(' then
      stack.Push(')')
    else if (bracket = ')') and (stack.Count = 0) then
    begin
      Result := False;
      exit;
    end
    else
    begin
      var top := stack.Pop;
      if top <> bracket then
      begin
        Result := False;
        exit;
      end;
    end;
  end;
  Result := stack.Count = 0;
end;


function Derivative(xs: array of real): array of real;
begin
  var n := xs.Length;
  if n <= 1 then
    Result := new real[0]
  else
  begin
    var res := new real[n - 1];
    for var i := 1 to n - 1 do
      res[i - 1] := (n - i) * xs[i];
    Result := res;
  end;
end;


