  for var i := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if grid[i, j] = 1 then
      begin
        buckets[i, j] := 1;
        for var k := 0 to n - 1 do
          if (k < i) and (grid[k, j] = 1) then
            buckets[k, j] += 1;
        for var k := 0 to m - 1 do
          if (k < j) and (grid[i, k] = 1) then
            buckets[i, k] += 1;
      end;

  for var i := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if grid[i, j] = 0 then
      begin
        var total := 0;
        for var k := 0 to n - 1 do
          if (k < i) and (grid[k, j] = 1) then
            total += 1;
        for var k := 0 to m - 1 do
          if (k < j) and (grid[i, k] = 1) then
            total += 1;
        if total <= capacity then
          res += 1;
      end;

  Result := res;
end;


