function Intersection(interval1, interval2: array of integer): string;
begin
  var start := Max(interval1[0], interval2[0]);
  var endVal := Min(interval1[1], interval2[1]);
  if start > endVal then
    Result := 'NO'
  else if (start + 1) mod 2 = 0 then
    Result := 'YES'
  else
    Result := 'NO';
end;


function ProdSigns(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var prod := 1;
  foreach var num in arr do
    if num < 0 then
      prod *= -1
    else if num > 0 then
      prod *= 1;

  var res := 0;
  foreach var num in arr do
    res += Abs(num) * prod;

  Result := res;
end;


function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := new List<(integer, integer)>;
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      directions.Add((i, j));
  directions.Sort((a, b) ->
  begin
    var (i1, j1) := a;
    var (i2, j2) := b;
    var (x1, y1) := (i1 + 1, j1 + 1);
    var (x2, y2) := (i2 + 1, j2 + 1);
    var (c1, c2) := (grid[x1 - 1][y1 - 1], grid[x2 - 1][y2 - 1]);
    var (d1, d2) := (c1 - c2, x1 - x2);
    var (e1, e2) := (y1 - y2, x1 - x2);
    if d1 * e2 - e1 * d2 = 0 then
      d1
    else
      d1 * e2 - e1 * d2
  end);
  var ans := new List<integer>;
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
    begin
      var (x, y) := (i + 1, j + 1);
      ans.Add(grid[x - 1][y - 1]);
      (i, j) := directions[0];
      directions.RemoveAt(0);
    end;
  Result := ans.ToArray;
end;


function Tri(n: integer): array of real;
begin
  var trib := new List<real>;
  trib.Add(3);
  if n > 0 then
  begin
    trib.Add(1);
    if n mod 2 = 0 then
      trib.Add(1)
    else
      trib.Add(1 + n div 2);
  end;
  for var i := 3 to n do
  begin
    if n mod 2 = 0 then
      trib.Add(trib[i - 1] + trib[i - 2] + trib[i - 3])
    else
      trib.Add(trib[i - 1] + trib[i - 2] + trib[i - 3] + 1);
  end;
  Result := trib.ToArray;
end;


function Digits(n: integer): integer;
begin
  var product := 1;
  var hasOdd := False;
  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 <> 0 then
    begin
      product := product * digit;
      hasOdd := True;
    end;
    n := n div 10;
  end;
  if hasOdd then
    Result := product
  else
    Result := 0;
end;


function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in s do
  begin
    if ch = '[' then
      stack.Push(ch)
    else if (ch = ']') and (stack.Count > 0) then
      stack.Pop
    else
    begin
      Result := False;
      exit;
    end;
  end;
  Result := stack.Count = 0;
end;


function SumSquares(lst: array of real): integer;
begin
  var sum := 0;
  for var i := 0 to lst.Length - 1 do
    sum += Round(lst[i]) * Round(lst[i]);
  Result := sum;
end;


function CheckIfLastCharIsALetter(txt: string): boolean;
begin
  if txt = '' then
  begin
    Result := False;
    exit;
  end;

  var lastChar := txt[txt.Length];
  if (lastChar in ['a'..'z']) or (lastChar in ['A'..'Z']) then
    Result := False
  else
    Result := True;
end;


function CanArrange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var maxIndex := 0;
  for var i := 1 to n - 1 do
  begin
    if arr[i] < arr[i - 1] then
    begin
      maxIndex := i;
      break;
    end;
  end;
  if maxIndex = 0 then
    Result := -1
  else
  begin
    for var i := maxIndex - 1 downto 0 do
    begin
      if arr[i] > arr[i + 1] then
      begin
        Result := i;
        exit;
      end;
    end;
    Result := maxIndex;
  end;
end;


function LargestSmallestIntegers(lst: array of integer): (integer, integer);
begin
  var neg := new List<integer>;
  var pos := new List<integer>;

  foreach var i in lst do
  begin
    if i < 0 then
      neg.Add(i)
    else if i > 0 then
      pos.Add(i);
  end;

  if neg.Count = 0 then
    Result := (0, pos.Min)
  else if pos.Count = 0 then
    Result := (neg.Max, 0)
  else
    Result := (neg.Max, pos.Min);
end;


function CompareOne(a, b: object): object;
begin
  if (a is integer) or (a is float) or (a is double) then
  begin
    if (b is integer) or (b is float) or (b is double) then
    begin
      var a1 := Convert.ToDouble(a);
      var b1 := Convert.ToDouble(b);
      if a1 > b1 then
        Result := b
      else if a1 < b1 then
        Result := a
      else
        Result := nil;
    end
    else
      Result := nil;
  end
  else if (b is integer) or (b is float) or (b is double) then
  begin
    var a1 := Convert.ToDouble(a);
    var b1 := Convert.ToDouble(b);
    if a1 > b1 then
      Result := a
    else if a1 < b1 then
      Result := b
    else
      Result := nil;
  end
  else
    Result := nil;
end;


function IsEqualToSumEven(n: integer): boolean;
begin
  if n mod 2 <> 0 then
    Result := False
  else
  begin
    var a := 2;
    var b := 4;
    var c := 2;
    var d := 2;
    var sum := a + b + c + d;
    while a + b + c + d <> n do
    begin
      c := c + 2;
      d := d + 2;
      sum := sum + c + d;
    end;
    if sum = n then
      Result := True
    else
      Result := False;
  end;
end;


function SpecialFactorial(n: integer): integer;
begin
  var res := 1;
  for var i := n downto 1 do
  begin
    var temp := 1;
    for var j := 1 to i do
      temp := temp * j;
    res := res * temp;
  end;
  Result := res;
end;


function FixSpaces(text: string): string;
begin
  var res := '';
  var count := 0;
  foreach var ch in text do
  begin
    if ch = ' ' then
    begin
      count += 1;
      if count = 1 then
        res += ch
      else if count = 2 then
        res += '_'
      else
        res += '-';
    end
    else
    begin
      res += ch;
      count := 0;
    end;
  end;
  Result := res;
end;


function FileNameCheck(fileName: string): string;
begin
  var parts := fileName.Split('.');
  if parts.Length <> 2 then
    Result := 'No'
  else
  begin
    var nameParts := parts[0].Split(' ', System.StringSplitOptions.RemoveEmptyEntries);
    if nameParts.Length <> 1 then
      Result := 'No'
    else
    begin
      var name := nameParts[0];
      if (name.Length > 3) or (not char.IsLetter(name[1])) or (not char.IsLetter(name[name.Length])) then
        Result := 'No'
      else
      begin
        var extension := parts[1];
        if (extension <> 'txt') and (extension <> 'exe') and (extension <> 'dll') then
          Result := 'No'
        else
          Result := 'Yes';
      end;
    end;
  end;
end;


function SumSquares(lst: array of integer): integer;
begin
  var total := 0;
  for var i := 0 to lst.Length - 1 do
  begin
    if i mod 3 = 0 then
      total += i * i
    else if i mod 4 = 0 then
      total += i * i * i
  end;
  Result := total;
end;


function WordsInSentence(sentence: string): string;
begin
  var words := sentence.Split(' ');
  var primeWords := new List<string>;

  for var i := 0 to words.Length - 1 do
    if IsPrime(words[i].Length) then
      primeWords.Add(words[i]);

  Result := string.Join(' ', primeWords);
end;


function Simplify(x, n: string): boolean;
begin
  var (num1, num2) := (StrToInt(x.Substring(0, x.Index('/'))), StrToInt(x.Substring(x.Index('/') + 1)));
  var (den1, den2) := (StrToInt(n.Substring(0, n.Index('/'))), StrToInt(n.Substring(n.Index('/') + 1)));
  Result := (num1 * den2) mod den1 = 0;
end;


function OrderByPoints(nums: array of integer): array of integer;
begin
  var sortedNums := nums.Select((num, i) -> (num, i)).OrderBy(x -> x.Item1.ToString.Sum(c -> StrToInt(c.ToString))).ToArray();
  Result := new integer[sortedNums.Length];
  for var i := 0 to sortedNums.Length - 1 do
    Result[i] := sortedNums[i].Item2;
end;


function Specialfilter(nums: array of integer): integer;
begin
  var count := 0;
  foreach var num in nums do
  begin
    if (num > 10) and (Abs(num mod 10) = 1) and (Abs(num div 10) = 1) then
      count += 1;
  end;
  Result := count;
end;


function GetMaxTriples(n: integer): integer;
begin
  var a := new integer[n];
  for var i := 0 to n - 1 do
    a[i] := i * i - i + 1;
  var res := 0;
  for var i := 0 to n - 1 do
    for var j := i + 1 to n - 1 do
      for var k := j + 1 to n - 1 do
        if (a[i] + a[j] + a[k]) mod 3 = 0 then
          res += 1;
  Result := res;
end;


function Bf(planet1, planet2: string): array of string;
begin
  var planets := new List<string>;
  var distances := new Dictionary<string, integer>;
  distances['Mercury'] := 1;
  distances['Venus'] := 2;
  distances['Earth'] := 3;
  distances['Mars'] := 4;
  distances['Jupiter'] := 5;
  distances['Saturn'] := 6;
  distances['Uranus'] := 7;
  distances['Neptune'] := 8;

  if (distances.ContainsKey(planet1) and distances.ContainsKey(planet2)) and 
     (distances[planet1] <= distances[planet2]) then
  begin
    for var i := distances[planet1] to distances[planet2] do
      planets.Add(i.ToString);
    Result := planets.ToArray;
  end
  else
    Result := #();
end;


function ListSort(lst: array of string): array of string;
begin
  var filtered := lst.Where(x -> x.Length mod 2 = 0);
  Result := filtered.OrderBy(x -> x.Length).ThenBy(x -> x).ToArray;
end;


function XOrY(n, x, y: integer): integer;
begin
  if n = 1 then
    Result := x
  else
    Result := y;
end;


function DoubleTheDifference(lst: array of real): integer;
begin
  var sumSquares := 0;
  foreach var num in lst do
    if (num >= 0) and (num = Trunc(num)) and (num mod 2 <> 0) then
      sumSquares += Round(num * num);
  Result := sumSquares;
end;


function Compare(game, guess: array of integer): array of integer;
begin
  var res := new integer[game.Length];
  for var i := 0 to game.Length - 1 do
    res[i] := Abs(game[i] - guess[i]);
  Result := res;
end;


function StrongestExtension(className: string; extensions: array of string): string;
begin
  var maxStrength := -1.0;
  var strongestExtension := '';

  foreach var extension in extensions do
  begin
    var uppercaseCount := 0;
    var lowercaseCount := 0;

    foreach var ch in extension do
    begin
      if ch.IsUpper then
        uppercaseCount += 1;
      if ch.IsLower then
        lowercaseCount += 1;
    end;

    var strength := uppercaseCount - lowercaseCount;
    if strength > maxStrength then
    begin
      maxStrength := strength;
      strongestExtension := extension;
    end;
  end;

  Result := className + '.' + strongestExtension;
end;


function CycpatternCheck(a, b: string): boolean;
begin
  for var i := 0 to b.Length - 1 do
  begin
    var rotated := b.Substring(i) + b.Substring(0, i);
    if rotated.Contains(a) then
    begin
      Result := True;
      exit;
    end;
  end;
  Result := False;
end;


function EvenOddCount(num: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  var numStr := Abs(num);

  while numStr > 0 do
  begin
    var digit := numStr mod 10;
    if digit mod 2 = 0 then
      evenCount += 1
    else
      oddCount += 1;
    numStr := numStr div 10;
  end;

  Result := (evenCount, oddCount);
end;


function IntToMiniRoman(number: integer): string;
begin
  if (number < 1) or (number > 1000) then
    raise new System.ArgumentException('Number must be between 1 and 1000');

  var roman := new List<(string, integer)>;
  roman.Add(('m', 1000));
  roman.Add(('cm', 900));
  roman.Add(('d', 500));
  roman.Add(('cd', 400));
  roman.Add(('c', 100));
  roman.Add(( 'xc', 90));
  roman.Add(( 'l', 50));
  roman.Add(( 'xl', 40));
  roman.Add(( 'x', 10));
  roman.Add(( 'ix', 9));
  roman.Add(( 'v', 5));
  roman.Add(( 'iv', 4));
  roman.Add(( 'i', 1));

  var result := '';
  while number > 0 do
  begin
    foreach var pair in roman do
    begin
      var (numeral, divisor) := pair;
      while number >= divisor do
      begin
        result += numeral;
        number -= divisor;
      end;
    end;
  end;
  Result := result;
end;


function RightAngleTriangle(a, b, c: integer): boolean;
begin
  if (a * a + b * b = c * c) or (a * a + c * c = b * b) or (b * b + c * c = a * a) then
    Result := True
  else
    Result := False;
end;


function FindMax(words: array of string): string;
begin
  var maxUnique := 0;
  var maxWord := '';
  foreach var word in words do
  begin
    var uniqueCount := word.Distinct.Count;
    if uniqueCount > maxUnique then
    begin
      maxUnique := uniqueCount;
      maxWord := word;
    end;
  end;
  Result := maxWord;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  var eaten := Min(need, remaining) - number;
  Result := (number + eaten, remaining - eaten);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var s := operand[0].ToString;
  for var i := 1 to operand.Length - 1 do
  begin
    s += op[i-1] + operand[i].ToString;
  end;
  Result := StrToInt(s);
end;


function Solve(s: string): string;
begin
  var letters := new List<char>;
  var digits := new List<char>;
  var specials := new List<char>;

  foreach var ch in s do
  begin
    if ch.IsLetter then
      letters.Add(ch)
    else if ch.IsDigit then
      digits.Add(ch)
    else
      specials.Add(ch);
  end;

  var ans := new List<char>;
  var l := 0;
  var d := 0;
  var s := 0;

  while (l < letters.Count) or (d < digits.Count) or (s < specials.Count) do
  begin
    if (l < letters.Count) and letters[l].IsLetter then
    begin
      ans.Add(letters[l].ToUpper);
      l += 1;
    end
    else if (d < digits.Count) and digits[d].IsDigit then
    begin
      ans.Add(digits[d]);
      d += 1;
    end
    else if (s < specials.Count) and not specials[s].IsLetter then
    begin
      ans.Add(specials[s]);
      s += 1;
    end;
  end;

  Result := new string(ans.ToArray);
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
  begin
    Result := '';
    exit;
  end;
  var h := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var m := new System.Text.StringBuilder;
  var b := new System.Text.StringBuilder(16);
  var a := (new System.Text.StringBuilder(text)).GetBytes(System.Text.Encoding.UTF8);
  h.ComputeHash(a);
  for var i := 0 to 3 do
    for var j := 0 to 1 do
      b.Append(h[i * 4 + j].ToString('x2'));
  Result := b.ToString;
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var res := new List<integer>;
  for var i := a to b do
    if i mod 2 = 0 then
      res.Add(i);
  Result := res.ToArray;
end;
